/**
 * @summary Possession counts per team
 */
export const GetPossessionsParams = zod.object({
  gameId: zod.coerce.number(),
});

export const GetPossessionsResponse = zod.object({
  gameId: zod.number(),
  currentPossessionTeamId: zod.number().nullish(),
  homeTeamId: zod.number(),
  awayTeamId: zod.number(),
  homePossessions: zod.number(),
  awayPossessions: zod.number(),
});

/**
 * @summary Update the live clock and current period
 */
export const UpdateClockParams = zod.object({
  gameId: zod.coerce.number(),
});

export const UpdateClockBody = zod.object({
  clockSeconds: zod.number().optional(),
  currentPeriod: zod.number().optional(),
});

export const UpdateClockResponse = zod.object({
  id: zod.number(),
  leagueId: zod.number().nullish(),
  competition: zod.string().nullish(),
  date: zod.coerce.date(),
  venue: zod.string().nullish(),
  status: zod.enum(["setup", "active", "final"]),
  captureMode: zod.enum(["simple", "complex"]),
  periodCount: zod.number(),
  periodDurationMins: zod.number(),
  overtimeCount: zod.number(),
  currentPeriod: zod.number(),
  clockSeconds: zod.number(),
  possessionTeamId: zod.number().nullish(),
  createdAt: zod.coerce.date(),
  updatedAt: zod.coerce.date(),
});
